def two_sum_sorted(a, t):
    """有序(非降序)数组对撞双指针求两数之和。
    i 从左、j 从右相向逼近;返回满足 a[i]+a[j]==t 的一对下标 (i, j)
    (0-based,i<j);无解返回 (-1, -1)。注:LC 167 要求返回 1-based,
    把结果各 +1 即可。"""
    i, j = 0, len(a) - 1
    while i < j:
        s = a[i] + a[j]
        if s == t:
            return (i, j)
        if s < t:        # 和偏小:只能让左端变大
            i += 1
        else:            # 和偏大:只能让右端变小
            j -= 1
    return (-1, -1)
